83	function exportTopLevelElements(
84	  node: LexicalNode,
85	  elementTransformers: Array<ElementTransformer | MultilineElementTransformer>,
86	  textTransformersIndex: Array<TextFormatTransformer>,
87	  textMatchTransformers: Array<TextMatchTransformer>,
88	): string | null {
89	  for (const transformer of elementTransformers) {
90	    if (!transformer.export) {
91	      continue;
92	    }
93	    const result = transformer.export(node, (_node) =>
94	      exportChildren(_node, textTransformersIndex, textMatchTransformers),
95	    );
96	
97	    if (result != null) {
98	      return result;
99	    }
100	  }
101	
102	  if ($isElementNode(node)) {
103	    return exportChildren(node, textTransformersIndex, textMatchTransformers);
104	  } else if ($isDecoratorNode(node)) {
