43	/**
44	 * Renders markdown from a string. The selection is moved to the start after the operation.
45	 */
46	export function createMarkdownImport(
47	  transformers: Array<Transformer>,
48	  shouldPreserveNewLines = false,
49	): (markdownString: string, node?: ElementNode) => void {
50	  const byType = transformersByType(transformers);
51	  const textFormatTransformersIndex = createTextFormatTransformersIndex(
52	    byType.textFormat,
53	  );
54	
55	  return (markdownString, node) => {
56	    const lines = markdownString.split('\n');
57	    const linesLength = lines.length;
58	    const root = node || $getRoot();
59	    root.clear();
60	
61	    for (let i = 0; i < linesLength; i++) {
62	      const lineText = lines[i];
63	
64	      const [imported, shiftedIndex] = $importMultiline(
65	        lines,
66	        i,
67	        byType.multilineElement,
68	        root,
69	      );
70	
71	      if (imported) {
72	        // If a multiline markdown element was imported, we don't want to process the lines that were part of it anymore.
73	        // There could be other sub-markdown elements (both multiline and normal ones) matching within this matched multiline element's children.
74	        // However, it would be the responsibility of the matched multiline transformer to decide how it wants to handle them.
75	        // We cannot handle those, as there is no way for us to know how to maintain the correct order of generated lexical nodes for possible children.
76	        i = shiftedIndex; // Next loop will start from the line after the last line of the multiline element
77	        continue;
78	      }
79	
80	      $importBlocks(
81	        lineText,
82	        root,
83	        byType.element,
84	        textFormatTransformersIndex,
85	        byType.textMatch,
86	        shouldPreserveNewLines,
87	      );
88	    }
89	
90	    const children = root.getChildren();
91	    for (const child of children) {
92	      // By default, removing empty paragraphs as md does not really
93	      // allow empty lines and uses them as delimiter.
94	      // If you need empty lines set shouldPreserveNewLines = true.
95	      if (
96	        !shouldPreserveNewLines &&
97	        isEmptyParagraph(child) &&
98	        root.getChildrenSize() > 1
99	      ) {
100	        child.remove();
101	        continue;
102	      }
103	      // Convert all '\t' into TabNode.
104	      if ($isElementNode(child)) {
105	        for (const textNode of child.getAllTextNodes()) {
106	          $normalizeMarkdownTextNode(textNode);
107	        }
108	      }
109	    }
110	
111	    if ($getSelection() !== null) {
